sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    current.auto_create_draft_document = true;
    if (current.auto_create_draft_document) {
        if (new sn_hr_core.hr_PdfUtils().isValidPdfTemplateForPreFill(current.pdf_template.sys_id)) {
            var pdfDraftSysId = new sn_hr_core.hr_PdfUtils().prefillPdfTemplate(current.pdf_template.sys_id, false, current.sys_id, current.sys_class_name, current.sys_id);
            if (gs.nil(pdfDraftSysId))
                gs.info('Error occurred while generating pdf for ' + current.sys_id);
        } else {
            if (current.pdf_template.changes())
                new sn_hr_core.GeneralHRForm().inactivateRelatedDrafts(current.sys_class_name, current.sys_id);
            var caseAjax = new sn_hr_core.hr_CaseAjax();
            var document = caseAjax.documentBody(current.sys_class_name, current.sys_id, current.sys_class_name, current.sys_id, 'true');
            caseAjax.setDocumentBody(document.body, current.sys_class_name, current.sys_id, current.sys_class_name, current.sys_id);
        }
    }

})(current, previous);
